/**
 * Hero Background Sketch
 * Generative particle network with interactive mouse behavior
 */

export function heroBackgroundSketch(p5) {
  let particles = [];
  let numParticles = 60;
  let mouse = { x: 0, y: 0 };
  let canvas;

  class Particle {
    constructor() {
      this.pos = p5.createVector(p5.random(p5.width), p5.random(p5.height));
      this.vel = p5.createVector(p5.random(-0.5, 0.5), p5.random(-0.5, 0.5));
      this.acc = p5.createVector(0, 0);
      this.size = p5.random(2, 5);
      this.alpha = p5.random(100, 200);
      this.color = p5.random() > 0.5
        ? [255, 107, 53]   // Primary orange
        : [0, 78, 137];    // Secondary blue
    }

    applyForce(force) {
      this.acc.add(force);
    }

    update() {
      // Update velocity and position
      this.vel.add(this.acc);
      this.vel.limit(2);
      this.pos.add(this.vel);
      this.acc.mult(0);

      // Wrap around edges
      if (this.pos.x < 0) this.pos.x = p5.width;
      if (this.pos.x > p5.width) this.pos.x = 0;
      if (this.pos.y < 0) this.pos.y = p5.height;
      if (this.pos.y > p5.height) this.pos.y = 0;
    }

    // Attract to mouse
    attractToMouse() {
      let mousePos = p5.createVector(mouse.x, mouse.y);
      let force = p5.constructor.Vector.sub(mousePos, this.pos);
      let distance = force.mag();

      if (distance < 200) {
        force.normalize();
        force.mult(0.3 * (1 - distance / 200));
        this.applyForce(force);
      }
    }

    display() {
      p5.noStroke();
      p5.fill(this.color[0], this.color[1], this.color[2], this.alpha);
      p5.circle(this.pos.x, this.pos.y, this.size);
    }
  }

  p5.setup = () => {
    canvas = p5.createCanvas(p5.windowWidth, p5.windowHeight);
    canvas.style('position', 'absolute');
    canvas.style('top', '0');
    canvas.style('left', '0');
    canvas.style('z-index', '1');
    canvas.style('pointer-events', 'none');

    // Create particles
    for (let i = 0; i < numParticles; i++) {
      particles.push(new Particle());
    }
  };

  p5.draw = () => {
    p5.clear();
    p5.background(10, 14, 39, 50); // Dark blue with some transparency

    // Update and draw particles
    for (let particle of particles) {
      particle.attractToMouse();
      particle.update();
      particle.display();
    }

    // Draw connections between nearby particles
    for (let i = 0; i < particles.length; i++) {
      for (let j = i + 1; j < particles.length; j++) {
        let distance = p5.dist(
          particles[i].pos.x,
          particles[i].pos.y,
          particles[j].pos.x,
          particles[j].pos.y
        );

        if (distance < 150) {
          let alpha = p5.map(distance, 0, 150, 80, 0);
          p5.stroke(255, 107, 53, alpha);
          p5.strokeWeight(0.5);
          p5.line(
            particles[i].pos.x,
            particles[i].pos.y,
            particles[j].pos.x,
            particles[j].pos.y
          );
        }
      }
    }
  };

  p5.windowResized = () => {
    p5.resizeCanvas(p5.windowWidth, p5.windowHeight);
  };

  p5.mouseMoved = () => {
    mouse.x = p5.mouseX;
    mouse.y = p5.mouseY;
  };
}
