import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import styled from 'styled-components';
import sankeyData from './sankey_viz/escuelas.json';

const SankeyContainer = styled.div`
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;

  canvas {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  }

  svg {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  }

  .node rect {
    cursor: move;
    fill-opacity: 1;
    shape-rendering: crispEdges;
  }

  .node text {
    pointer-events: none;
    font-family: 'Inter', sans-serif;
    font-weight: 600;
    font-size: 14px;
  }

  .link {
    fill: none;
    stroke: #000;
    stroke-opacity: .08;
  }

  .link:hover {
    stroke-opacity: .2;
  }

  .percentage-label {
    font-family: 'Inter', sans-serif;
    font-size: 13px;
    font-weight: 700;
    pointer-events: none;
  }

  .bar-label {
    font-family: 'Inter', sans-serif;
    font-size: 14px;
    font-weight: 600;
    text-anchor: middle;
  }

  .bar-percentage {
    font-family: 'Inter', sans-serif;
    font-size: 15px;
    font-weight: 700;
    text-anchor: middle;
  }
`;

// D3 Sankey plugin implementation
const d3Sankey = () => {
  let sankey = {},
      nodeWidth = 24,
      nodePadding = 8,
      size = [1, 1],
      nodes = [],
      links = [];

  sankey.nodeWidth = function(_) {
    if (!arguments.length) return nodeWidth;
    nodeWidth = +_;
    return sankey;
  };

  sankey.nodePadding = function(_) {
    if (!arguments.length) return nodePadding;
    nodePadding = +_;
    return sankey;
  };

  sankey.nodes = function(_) {
    if (!arguments.length) return nodes;
    nodes = _;
    return sankey;
  };

  sankey.links = function(_) {
    if (!arguments.length) return links;
    links = _;
    return sankey;
  };

  sankey.size = function(_) {
    if (!arguments.length) return size;
    size = _;
    return sankey;
  };

  sankey.layout = function(iterations) {
    computeNodeLinks();
    computeNodeValues();
    computeNodeBreadths();
    computeNodeDepths(iterations);
    computeLinkDepths();
    return sankey;
  };

  sankey.relayout = function() {
    computeLinkDepths();
    return sankey;
  };

  sankey.link = function() {
    let curvature = .5;

    function link(d) {
      const x0 = d.source.x + d.source.dx,
            x1 = d.target.x,
            xi = d3.interpolateNumber(x0, x1),
            x2 = xi(curvature),
            x3 = xi(1 - curvature),
            y0 = d.source.y + d.sy + d.dy / 2,
            y1 = d.target.y + d.ty + d.dy / 2;
      return "M" + x0 + "," + y0
           + "C" + x2 + "," + y0
           + " " + x3 + "," + y1
           + " " + x1 + "," + y1;
    }

    link.curvature = function(_) {
      if (!arguments.length) return curvature;
      curvature = +_;
      return link;
    };

    return link;
  };

  function computeNodeLinks() {
    nodes.forEach(function(node) {
      node.sourceLinks = [];
      node.targetLinks = [];
    });
    links.forEach(function(link) {
      let source = link.source,
          target = link.target;
      if (typeof source === "number") source = link.source = nodes[link.source];
      if (typeof target === "number") target = link.target = nodes[link.target];
      source.sourceLinks.push(link);
      target.targetLinks.push(link);
    });
  }

  function computeNodeValues() {
    nodes.forEach(function(node) {
      node.value = Math.max(
        d3.sum(node.sourceLinks, value),
        d3.sum(node.targetLinks, value)
      );
    });
  }

  function computeNodeBreadths() {
    let remainingNodes = nodes,
        nextNodes,
        x = 0;

    while (remainingNodes.length) {
      nextNodes = [];
      const currentX = x;
      const currentNodeWidth = nodeWidth;
      remainingNodes.forEach((node) => {
        node.x = currentX;
        node.dx = currentNodeWidth;
        node.sourceLinks.forEach((link) => {
          if (nextNodes.indexOf(link.target) < 0) {
            nextNodes.push(link.target);
          }
        });
      });
      remainingNodes = nextNodes;
      ++x;
    }

    moveSinksRight(x);
    scaleNodeBreadths((size[0] - nodeWidth) / (x - 1));
  }

  function moveSinksRight(x) {
    nodes.forEach(function(node) {
      if (!node.sourceLinks.length) {
        node.x = x - 1;
      }
    });
  }

  function scaleNodeBreadths(kx) {
    nodes.forEach(function(node) {
      node.x *= kx;
    });
  }

  function computeNodeDepths(iterations) {
    // Group nodes by x position (breadth)
    const grouped = d3.group(nodes, d => d.x);
    const nodesByBreadth = Array.from(grouped.entries())
        .sort((a, b) => d3.ascending(a[0], b[0]))
        .map(d => d[1]);

    initializeNodeDepth();
    resolveCollisions();
    for (let alpha = 1; iterations > 0; --iterations) {
      relaxRightToLeft(alpha *= .99);
      resolveCollisions();
      relaxLeftToRight(alpha);
      resolveCollisions();
    }

    function initializeNodeDepth() {
      const ky = d3.min(nodesByBreadth, function(nodes) {
        return (size[1] - (nodes.length - 1) * nodePadding) / d3.sum(nodes, value);
      });

      nodesByBreadth.forEach(function(nodes) {
        nodes.forEach(function(node, i) {
          node.y = i;
          node.dy = node.value * ky;
        });
      });

      links.forEach(function(link) {
        link.dy = link.value * ky;
      });
    }

    function relaxLeftToRight(alpha) {
      nodesByBreadth.forEach(function(nodes) {
        nodes.forEach(function(node) {
          if (node.targetLinks.length) {
            const y = d3.sum(node.targetLinks, weightedSource) / d3.sum(node.targetLinks, value);
            node.y += (y - center(node)) * alpha;
          }
        });
      });

      function weightedSource(link) {
        return center(link.source) * link.value;
      }
    }

    function relaxRightToLeft(alpha) {
      nodesByBreadth.slice().reverse().forEach(function(nodes) {
        nodes.forEach(function(node) {
          if (node.sourceLinks.length) {
            const y = d3.sum(node.sourceLinks, weightedTarget) / d3.sum(node.sourceLinks, value);
            node.y += (y - center(node)) * alpha;
          }
        });
      });

      function weightedTarget(link) {
        return center(link.target) * link.value;
      }
    }

    function resolveCollisions() {
      nodesByBreadth.forEach(function(nodes) {
        let node,
            dy,
            y0 = 0,
            n = nodes.length,
            i;

        nodes.sort(ascendingDepth);
        for (i = 0; i < n; ++i) {
          node = nodes[i];
          dy = y0 - node.y;
          if (dy > 0) node.y += dy;
          y0 = node.y + node.dy + nodePadding;
        }

        dy = y0 - nodePadding - size[1];
        if (dy > 0) {
          y0 = node.y -= dy;

          for (i = n - 2; i >= 0; --i) {
            node = nodes[i];
            dy = node.y + node.dy + nodePadding - y0;
            if (dy > 0) node.y -= dy;
            y0 = node.y;
          }
        }
      });
    }

    function ascendingDepth(a, b) {
      return a.y - b.y;
    }
  }

  function computeLinkDepths() {
    nodes.forEach(function(node) {
      node.sourceLinks.sort(ascendingTargetDepth);
      node.targetLinks.sort(ascendingSourceDepth);
    });
    nodes.forEach(function(node) {
      let sy = 0, ty = 0;
      node.sourceLinks.forEach(function(link) {
        link.sy = sy;
        sy += link.dy;
      });
      node.targetLinks.forEach(function(link) {
        link.ty = ty;
        ty += link.dy;
      });
    });

    function ascendingSourceDepth(a, b) {
      return a.source.y - b.source.y;
    }

    function ascendingTargetDepth(a, b) {
      return a.target.y - b.target.y;
    }
  }

  function center(node) {
    return node.y + node.dy / 2;
  }

  function value(link) {
    return link.value;
  }

  return sankey;
};

const SankeyViz = () => {
  const svgRef = useRef(null);
  const canvasRef = useRef(null);
  const animationRef = useRef(null);
  const containerRef = useRef(null);

  useEffect(() => {
    if (!svgRef.current || !canvasRef.current) return;

    // Calculate responsive dimensions based on viewport
    const viewportWidth = typeof window !== 'undefined' ? window.innerWidth : 1200;
    const viewportHeight = typeof window !== 'undefined' ? window.innerHeight : 800;

    // Use container-based sizing for better responsiveness
    const containerWidth = containerRef.current?.offsetWidth || viewportWidth * 0.8;
    const containerHeight = containerRef.current?.offsetHeight || viewportHeight * 0.8;

    const totalWidth = Math.min(containerWidth, 1200);
    const totalHeight = Math.min(containerHeight, 600);

    const margin = {
      top: totalHeight * 0.1,
      right: totalWidth * 0.2,  // Increased right margin for labels
      bottom: totalHeight * 0.1,
      left: totalWidth * 0.15
    };
    const width = totalWidth - margin.left - margin.right;
    const height = totalHeight - margin.top - margin.bottom;

    // Setup canvas
    const canvas = canvasRef.current;
    canvas.width = width + margin.left + margin.right;
    canvas.height = height + margin.top + margin.bottom;

    // Setup SVG
    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();
    svg
      .attr('width', width + margin.left + margin.right)
      .attr('height', height + margin.top + margin.bottom);

    const g = svg.append('g')
      .attr('transform', `translate(${margin.left},${margin.top})`);

    // Create sankey layout
    const sankey = d3Sankey()
      .nodeWidth(20)
      .nodePadding(30)
      .size([width, height]);

    const path = sankey.link();

    // Color palette
    const myColor = [
      "#c1666b",  // Comunitaria
      "#4281a4",  // General Pública
      "#48a9a6",  // Privada
      "#d4b483",  // Técnica Pública
      "#8b7e74",  // Telesecundaria
      "#d64045",  // Poor
      "#e9806e",  // Insufficient
      "#f4a261",  // Sufficient
      "#2a9d8f"   // Outstanding
    ];

    const levelLabels = {
      "I": "Pobre",
      "II": "Insuficiente",
      "III": "Suficiente",
      "IV": "Sobresaliente"
    };

    const formatNumber = d3.format(",.1f");
    const format = (d) => formatNumber(d) + "%";

    // Layout the sankey diagram
    sankey
      .nodes(sankeyData.nodes)
      .links(sankeyData.links)
      .layout(30);

    // Draw links
    const link = g.append('g').selectAll('.link')
      .data(sankeyData.links)
      .enter().append('path')
      .attr('class', 'link')
      .attr('d', path)
      .style('stroke-opacity', 0.12)
      .style('stroke-width', (d) => Math.max(1, d.dy))
      .sort((a, b) => b.dy - a.dy);

    link.append('title')
      .text((d) => d.source.name + " → " + d.target.name + "\n" + format(d.value));

    // Draw nodes
    const node = g.append('g').selectAll('.node')
      .data(sankeyData.nodes)
      .enter().append('g')
      .attr('class', 'node')
      .attr('transform', (d) => `translate(${d.x},${d.y})`)
      .call(d3.drag()
        .on('start', function() { this.parentNode.appendChild(this); })
        .on('drag', dragmove));

    node.append('rect')
      .attr('height', (d) => d.dy)
      .attr('width', sankey.nodeWidth())
      .style('fill', (d, i) => { d.color = myColor[i]; return d.color; })
      .style('stroke', 'none')
      .style('fill-opacity', (d) => d.x >= width / 2 ? 0 : 1)
      .attr('rx', 3)
      .append('title')
      .text((d) => d.name + "\n" + format(d.value));

    // Left side labels
    node.filter((d) => d.x < width / 2)
      .append('text')
      .attr('x', -12)
      .attr('y', (d) => d.dy / 2)
      .attr('dy', '.35em')
      .attr('text-anchor', 'end')
      .text((d) => d.name)
      .style('fill', (d) => d.color)
      .style('font-size', '14px')
      .style('font-weight', '600')
      .style('paint-order', 'stroke')
      .style('stroke', 'rgba(0, 0, 0, 0.3)')
      .style('stroke-width', '3px');

    // Calculate averages for right side
    const levelTotals = {"I": 0, "II": 0, "III": 0, "IV": 0};
    const levelCounts = {"I": 0, "II": 0, "III": 0, "IV": 0};

    sankeyData.links.forEach((link) => {
      levelTotals[link.target.name] += link.value;
      levelCounts[link.target.name] += 1;
    });

    Object.keys(levelTotals).forEach((level) => {
      levelTotals[level] = levelTotals[level] / levelCounts[level];
    });

    const rightLabelX = width + 25;

    // Right side labels
    const rightNodes = node.filter((d) => d.x >= width / 2);

    rightNodes.each(function(d) {
      const yPos = d.y + d.dy / 2;

      g.append('text')
        .attr('class', 'bar-label')
        .attr('x', rightLabelX)
        .attr('y', yPos - 5)
        .attr('text-anchor', 'start')
        .text(levelLabels[d.name] || d.name)
        .style('fill', d.color)
        .style('font-size', '15px')
        .style('font-weight', '600')
        .style('paint-order', 'stroke')
        .style('stroke', 'rgba(0, 0, 0, 0.3)')
        .style('stroke-width', '3px');

      g.append('text')
        .attr('class', 'bar-percentage')
        .attr('x', rightLabelX)
        .attr('y', yPos + 12)
        .attr('text-anchor', 'start')
        .style('fill', '#ccc')
        .style('font-size', '14px')
        .text(formatNumber(levelTotals[d.name]) + "%");
    });

    function dragmove(event, d) {
      d3.select(this).attr('transform',
        `translate(${d.x},${d.y = Math.max(0, Math.min(height - d.dy, event.y))})`
      );
      sankey.relayout();
      link.attr('d', path);
    }

    // Particle animation setup
    const linkExtent = d3.extent(sankeyData.links, (d) => d.value);
    const frequencyScale = d3.scaleLinear().domain(linkExtent).range([1, 100]);
    const particleSize = d3.scaleLinear().domain(linkExtent).range([2.5, 2.5]);

    link.style('stroke', (d) => d.source.color);

    sankeyData.links.forEach((link) => {
      link.freq = frequencyScale(link.value);
      link.particleSize = particleSize(link.value);
      link.particleColor = d3.scaleLinear().domain([1, 1000]).range([link.source.color, link.source.color]);
    });

    // Animation variables
    let particles = [];
    let freqCounter = 1;
    let borrar = totalWidth;  // Use full width for clearing
    let recorr = 0;
    let startTime = Date.now();

    function tick() {
      const elapsed = Date.now() - startTime;

      particles = particles.filter((d) => d.time > (elapsed - 2500));

      if (freqCounter > 300) {
        freqCounter = 1;
        borrar = totalWidth;
        recorr = 0;
      }

      d3.selectAll('path.link').each(function(d) {
        if (d.freq >= freqCounter) {
          for (let i = 0; i < 1; i++) {
            const offset = (Math.random() - .5) * d.dy;
            particles.push({ link: d, time: elapsed, offset: offset, path: this });
            particles.push({ link: d, time: elapsed + 0.001, offset: (Math.random() - .5) * d.dy, path: this });
          }
        }
      });

      particleEdgeCanvasPath(elapsed);
      freqCounter = freqCounter + 0.2;
      borrar = borrar - 0.18;
      recorr = recorr + 0.18;

      animationRef.current = requestAnimationFrame(tick);
    }

    const redu = 0.5;
    function particleEdgeCanvasPath(elapsed) {
      const context = canvas.getContext('2d');
      context.clearRect(0, 0, borrar, canvas.height);

      for (let x in particles) {
        const currentTime = (elapsed - particles[x].time) * redu;
        const currentPercent = ((currentTime) / (980)) * (particles[x].path.getTotalLength());
        const currentPos = particles[x].path.getPointAtLength(currentPercent - Math.random() * recorr);

        context.beginPath();
        context.fillStyle = particles[x].link.particleColor(currentTime);
        context.globalAlpha = 0.7;
        context.arc(
          currentPos.x + margin.left,
          currentPos.y + margin.top + particles[x].offset,
          particles[x].link.particleSize,
          0,
          2 * Math.PI
        );
        context.fill();
        context.globalAlpha = 1.0;
      }
    }

    // Start animation
    tick();

    // Cleanup
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  return (
    <SankeyContainer ref={containerRef}>
      <canvas ref={canvasRef} />
      <svg ref={svgRef} />
    </SankeyContainer>
  );
};

export default SankeyViz;
