import React, { lazy, Suspense } from 'react';
import styled from 'styled-components';

// Lazy load P5Wrapper to avoid SSR issues
const P5Wrapper = typeof window !== 'undefined'
  ? lazy(() => import('@p5-wrapper/react').then(module => ({ default: module.ReactP5Wrapper })))
  : null;

const SketchContainer = styled.div`
  width: 100%;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: ${props => props.backgroundColor || 'transparent'};
  border-radius: ${props => props.theme.radii.lg};
  overflow: hidden;

  canvas {
    display: block;
    max-width: 100%;
    height: auto;
  }
`;

const LoadingContainer = styled.div`
  width: 100%;
  min-height: ${props => props.minHeight || '400px'};
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: var(--color-surface);
  border-radius: ${props => props.theme.radii.lg};
  color: var(--color-text-secondary);
  font-size: ${props => props.theme.typography.fontSizes.lg};
`;

const ErrorContainer = styled(LoadingContainer)`
  background-color: rgba(239, 68, 68, 0.1);
  border: 1px solid ${props => props.theme.colors.error};
  color: ${props => props.theme.colors.error};
`;

/**
 * SSR-safe P5.js Sketch Wrapper
 *
 * Usage:
 * <P5Sketch sketch={sketchFunction} minHeight="600px" backgroundColor="#0A0E27" />
 *
 * @param {Function} sketch - p5.js sketch function
 * @param {string} minHeight - minimum height of container
 * @param {string} backgroundColor - background color
 */
function P5Sketch({ sketch, minHeight = '400px', backgroundColor, ...props }) {
  // Check if we're on the server
  const isSSR = typeof window === 'undefined';

  if (isSSR) {
    return (
      <LoadingContainer minHeight={minHeight}>
        <span>Loading visualization...</span>
      </LoadingContainer>
    );
  }

  if (!P5Wrapper) {
    return (
      <ErrorContainer minHeight={minHeight}>
        <span>Error: Unable to load P5 visualization</span>
      </ErrorContainer>
    );
  }

  return (
    <SketchContainer backgroundColor={backgroundColor}>
      <Suspense
        fallback={
          <LoadingContainer minHeight={minHeight}>
            <span>Loading visualization...</span>
          </LoadingContainer>
        }
      >
        <P5Wrapper sketch={sketch} {...props} />
      </Suspense>
    </SketchContainer>
  );
}

export default P5Sketch;
